        x=137+j*24
        parts.append(f'<circle cx="{x}" cy="{y+57}" r="7" fill="#394444" stroke="#839494"/><path d="M{x} {y+51}v5" stroke="{color}" stroke-width="2"/><rect x="{x-7}" y="{y+76}" width="14" height="9" rx="1.5" fill="{color if j in [0,3,6] else "#4e5a5a"}"/>')
