parts.append('''<path d="M103 757h1194" stroke="#424d58"/><rect x="105" y="777" width="47" height="42" rx="6" fill="#323e49" stroke="#647382"/><path d="M132 790l-8 8 8 8" fill="none" stroke="#c0cfda" stroke-width="2"/><text x="190" y="805" fill="#d1dce5" text-anchor="middle" font-size="17">1 / …</text><rect x="229" y="777" width="47" height="42" rx="6" fill="#323e49" stroke="#647382"/><path d="M248 790l8 8-8 8" fill="none" stroke="#c0cfda" stroke-width="2"/>
<text x="647" y="797" fill="#bccbd7" text-anchor="middle" font-size="14">Discover your next sound.</text><text x="647" y="819" fill="#8194a3" text-anchor="middle" font-size="11">Community instruments &amp; effects</text>
<rect x="930" y="777" width="192" height="42" rx="6" fill="#536c80"/><text x="1026" y="804" fill="#fff" text-anchor="middle" font-size="16">Refresh catalog</text><rect x="1135" y="777" width="160" height="42" rx="6" fill="#303c48"/><text x="1215" y="804" fill="#92a4b3" text-anchor="middle" font-size="14">CONTINUE</text>
<path d="M104 846h135" stroke="#f18050" stroke-width="4" stroke-linecap="round"/><text x="80" y="941" fill="#f2f4f6" font-size="25" font-weight="700">Find it. Install it. Play.</text><text x="1320" y="940" text-anchor="end" fill="#c2ced7" font-size="20">200+ community synths &amp; effects</text><text x="80" y="981" fill="#8396a4" font-size="15">Illustrated interface · representative plugin cards</text><text x="1320" y="981" text-anchor="end" fill="#8396a4" font-size="15" letter-spacing="2">FORCE + MPC GEN1</text></g></svg>''')
